## ---- 01: Key-Rate-Duration Matching as a Linear System  (qmd line 67) ---------------

# Solve hedge notionals via least squares
# D_hedge is [n_tenors x n_instruments]; d_pool is n_tenors vector
hedge_notionals <- function(D_hedge, d_pool) {
  -solve(t(D_hedge) %*% D_hedge, t(D_hedge) %*% d_pool)
}


## ---- 02: Duration-Match Hedge (User Helpers Built on `oasr` Outputs)  (qmd line 242) -

library(oasr)

# Pool's effective duration and base value from oasr
dc <- calculate_duration_convexity(pool_cf, rate_paths,
                                    oas = oas_result$oas, shock = 100,
                                    asset_level = FALSE, total_idx = 5)
pv <- calculate_present_value(pool_cf, rate_paths,
                               oas = oas_result$oas,
                               asset_level = FALSE, total_idx = 5)
V0 <- sum(pv$mean_pvs)
w  <- pv$mean_pvs / V0
# oasr's duration carries the opposite of the conventional sign;
# negate and value-weight across bonds for the pool-level number
duration <- -sum(dc$duration * w)

# DV01 of pool ($ per 1 bp parallel rate move)
dv01_pool <- duration * V0 / 10000

# 5Y Treasury future contract
dv01_5y     <- 60   # $ per contract per bp (from CME)
n_contracts <- -dv01_pool / dv01_5y
n_contracts


## ---- 03: KR-Match Linear System  (qmd line 269) --------------------------------------

# Pool's KR DV01 vector ($/bp at each tenor)
kr_dv01_pool <- krd_vec * V0 / 10000

# Hedge instruments' KR DV01 (rows = tenors, cols = instruments)
hedge_dv01 <- matrix(c(
  # 2Y, 5Y, 10Y, Ultra-10
  35, 0, 0, 0,           # 2Y
  10, 50, 0, 0,           # 5Y
  0, 8, 80, 5,            # 10Y
  0, 0, 0, 130            # 30Y
), nrow = 4, byrow = TRUE)

hedge_notionals <- -solve(t(hedge_dv01) %*% hedge_dv01,
                           t(hedge_dv01) %*% kr_dv01_pool)
hedge_notionals


## ---- 04: Regression Hedging  (qmd line 289) ------------------------------------------

# Use historical daily P&L to fit hedge betas
fit_hedge <- lm(pnl_pool ~ pnl_2y + pnl_5y + pnl_10y - 1,
                data = historical_pnl)
betas <- coef(fit_hedge)
hedge_check <- with(historical_pnl,
  pnl_pool - cbind(pnl_2y, pnl_5y, pnl_10y) %*% betas)
sd(hedge_check) / sd(historical_pnl$pnl_pool)   # tracking ratio


## ---- 05: Convexity / Gamma Hedge  (qmd line 301) -------------------------------------

# Long swaption straddle to neutralize negative convexity
gamma_swaption <- function(notional, vol, expiry, tenor) {
  # Approximate gamma per $ notional
  notional * vol * sqrt(expiry) / tenor
}

convexity <- sum(dc$convexity * w)   # value-weighted pool convexity
target_gamma <- -convexity * V0
straddle_size <- target_gamma / gamma_swaption(1, vol = 0.20,
                                                expiry = 1,
                                                tenor = 5)


## ---- 06: P&L Attribution Under Hedge  (qmd line 317) ---------------------------------

attribute_hedged_pnl <- function(pnl_pool, pnl_hedge, sens, mkt) {
  total_pnl <- pnl_pool + pnl_hedge
  parts <- list(
    duration_resid = -sens$D * mkt$parallel * V0 + sum(hedge_dv01),
    convexity      = 0.5 * sens$C * mkt$parallel^2 * V0,
    spread         = -sens$Dspr * mkt$spread * V0
  )
  c(list(pre_hedge = pnl_pool, hedge_offset = pnl_hedge),
    parts,
    list(residual = total_pnl - sum(unlist(parts))))
}


## ---- 07: VaR and Expected Shortfall  (qmd line 333) ----------------------------------

library(PerformanceAnalytics)

spread_dur <- duration   # ≈ modified duration for a constant-spread OAS
scenario_pnl <- replicate(10000, {
  d_y  <- rnorm(1, sd = 0.0008)
  d_kr <- rnorm(length(krd_vec), sd = 0.0006)
  d_s  <- rnorm(1, sd = 0.0005)
  -duration*V0*d_y +
   sum(krd_vec*V0*(d_kr - d_y)) -
   spread_dur*V0*d_s
})

var_95 <- -quantile(scenario_pnl, 0.05)
es_975 <- -mean(scenario_pnl[scenario_pnl < quantile(scenario_pnl, 0.025)])
list(var_95 = var_95, es_975 = es_975)

# Cross-check on the return-scale distribution
VaR(scenario_pnl / V0, p = 0.95,  method = "historical")
ES(scenario_pnl / V0,  p = 0.975, method = "historical")


## ---- 08: Dynamic Rebalancing  (qmd line 357) -----------------------------------------

needs_rebalance <- function(current_dur, target_dur,
                             threshold = 0.20) {
  abs(current_dur - target_dur) > threshold
}

# Daily check: current_dur comes from the morning risk run
if (needs_rebalance(current_dur, 0)) {
  trade_size <- (current_dur - 0) * V0 / dv01_5y / 10000
  message(sprintf("rebalance: trade %.0f contracts of 5Y futures",
                  trade_size))
}


## ---- 09: Hedge Effectiveness Test (ASC 815)  (qmd line 373) --------------------------

test_hedge_effectiveness <- function(pnl_pool, pnl_hedge,
                                      threshold = 0.80) {
  fit <- lm(pnl_pool ~ pnl_hedge - 1)
  r2  <- summary(fit)$r.squared
  list(slope = coef(fit), r2 = r2,
       effective = r2 >= threshold)
}


